// Count how many chapters were processed
const loopResults = $('Loop Over Chapters').all();
const chaptersProcessed = loopResults.length;
const manuscriptId = $('Webhook').first().json.body.manuscriptId;

console.log(`✅ Generated summaries for ${chaptersProcessed} chapters`);

return {
  json: {
    success: true,
    manuscriptId: manuscriptId,
    chaptersProcessed: chaptersProcessed,
    message: `Chapter summaries generated for ${chaptersProcessed} chapters`,
    timestamp: new Date().toISOString()
  }
};

const ch = $input.item.json;

const systemPrompt = `You are Alex, a developmental editor creating reference summaries. Create a concise 2-3 sentence summary that captures what happens in this chapter and why it matters to the overall story arc.  Focus on: key events, character decisions, and story progression.`;

const userPrompt = `Chapter ${ch.chapter_number}: "${ch.title}"

Content:
${ch.content}

Provide a 2-3 sentence summary that captures the essential events and character developments. Return ONLY the summary text, no preamble or explanation.`;

return { json: { system: systemPrompt, user: userPrompt, chapter_id: ch.id, chapter_number: ch.chapter_number } };

const cellReturn = $input.first().json;
return [{ json: {
  text: cellReturn.ok ? (cellReturn.content || '') : '',
  ok: !!cellReturn.ok,
  cell_terminal_reason: cellReturn.ok ? null : (cellReturn.terminal_reason || 'unknown'),
  cell_stop_reason: cellReturn.stop_reason || null,
  cell_input_tokens: cellReturn.input_tokens || null,
  cell_output_tokens: cellReturn.output_tokens || null,
  cell_cost_usd: cellReturn.cost_estimate_usd || null
}}];

